package connect

import "errors"

// directions are the six neighbours of a cell in the skewed hex grid.
//
// The board is a parallelogram in which each row is indented one field to
// the right, so the fields below a given one sit one field to the left and
// one field to the right of it.
var directions = [6][2]int{
	{-1, 0}, {-1, 1},
	{0, -1}, {0, 1},
	{1, -1}, {1, 0},
}

// ResultOf computes the winner of a game of Hex / Polygon.
//
// The board is given as a slice of strings, one per row, where 'X' and 'O'
// are stones and any other character (typically '.') is an empty field.
// Player "O" plays from top to bottom and player "X" plays from left to
// right: the first player to connect their stones to the opposite side wins.
//
// ResultOf returns "X" or "O" if that player has such a connection, or ""
// if nobody has won yet. An error is returned only for boards whose rows do
// not all have the same length.
func ResultOf(lines []string) (string, error) {
	if len(lines) == 0 {
		return "", nil
	}

	width := len(lines[0])
	for _, l := range lines {
		if len(l) != width {
			return "", errors.New("connect: board rows must all have the same length")
		}
	}

	// In a legal game of Hex both players can never have a connection at
	// once, but for an arbitrary board check X first so the result is
	// deterministic.
	if hasConnection(lines, 'X', false) {
		return "X", nil
	}
	if hasConnection(lines, 'O', true) {
		return "O", nil
	}
	return "", nil
}

// hasConnection reports whether the player's stones contain a connected
// chain from one side of the board to the opposite side.
//
// If alongRows is true the player must connect the top row to the bottom row
// (player O); otherwise the player must connect the left column to the right
// column (player X).
func hasConnection(board []string, player byte, alongRows bool) bool {
	height := len(board)
	width := len(board[0])

	visited := make([][]bool, height)
	for i := range visited {
		visited[i] = make([]bool, width)
	}

	// Seed the flood fill from every one of the player's stones on the
	// starting side.
	queue := make([][2]int, 0, height*width)
	for i := 0; i < height; i++ {
		for j := 0; j < width; j++ {
			onEdge := (alongRows && i == 0) || (!alongRows && j == 0)
			if onEdge && board[i][j] == player {
				visited[i][j] = true
				queue = append(queue, [2]int{i, j})
			}
		}
	}

	for len(queue) > 0 {
		cell := queue[0]
		queue = queue[1:]
		i, j := cell[0], cell[1]

		onGoal := (alongRows && i == height-1) || (!alongRows && j == width-1)
		if onGoal {
			return true
		}

		for _, d := range directions {
			n, m := i+d[0], j+d[1]
			if n < 0 || n >= height || m < 0 || m >= width {
				continue
			}
			if visited[n][m] || board[n][m] != player {
				continue
			}
			visited[n][m] = true
			queue = append(queue, [2]int{n, m})
		}
	}

	return false
}

